def countBoxes(capacity):
    boxes = 0
    for i in range(len(quantities)):
        remaining = quantities[i]
        while remaining > 0:
            itemsThisBox = min(
                capacity,
                maxWeightPerBox // weights[i],
                remaining
            )
            boxes += 1
            remaining -= itemsThisBox
    return boxes

# Binary search
left, right = 1, max(quantities)
while left < right:
    mid = (left + right) // 2
    if countBoxes(mid) <= maxBoxes:
        right = mid  # Try smaller
    else:
        left = mid + 1
return left
